INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('e-fresh', 'E · fresh builds', 'Each build starts from its brief in an empty working directory. Sol 6.1, Astra 6 and Opus 5.5 receive the same E prompt, at high effort. No previous build source, images or visual feedback.', 90, 1);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('f-fresh', 'F · fresh builds', 'Sol 6.1 at high effort starts from each brief in an empty working directory with prompt F. No previous build source, images or visual feedback. One run per brief; differences can include prompt variance.', 80, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('e-revision', 'E · source revisions', 'Sol 6.1, Astra 6 and Opus 5.5 at high effort revise the original Sol creative builds with prompt E. Previous build source is supplied. No images or visual feedback.', 70, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('f-revision', 'F · source revisions', 'Sol 6.1 at high effort revises the original Sol creative builds with prompt F. Previous build source is supplied. No images or visual feedback.', 60, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('c-text', 'C · fresh builds', 'Sol 6.1 at high effort generates four builds from their briefs using the finished-object prompt C. These four runs receive no previous build source, images or visual feedback. The image-assisted bird experiments are excluded.', 50, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('b-text', 'B · fresh builds', 'Sol 6.1 at high effort generates the two bird briefs with prompt B, informed by studying public LDraw models. The agent receives no previous build source, images or visual feedback.', 40, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('a-text', 'A · fresh builds', 'Sol 6.1 at high effort generates the two bird briefs with the object-first prompt A. No previous build source, images or visual feedback.', 30, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('creative', 'Original · creative prompt', 'The previous gallery collection: Sol 6.1 and Opus 5.5 at high effort generate all six briefs with the original creative prompt. No previous build source, images or visual feedback.', 20, 0);
INSERT OR IGNORE INTO generations (id, name, description, sort_order, is_default) VALUES ('earlier', 'Earlier · original rules', 'Earlier text-only gallery runs: temple builds across reasoning efforts and two Ewok briefs with different part targets. These use earlier building rules and are not a controlled comparison with E.', 10, 0);
